ANNOTATIONS = [
    (46, 'before', r'''StructuredMessage 判别联合：三种跨代理协议消息——shutdown_request（请求对方关机）、shutdown_response（批准/拒绝关机）、plan_approval_response（计划审批回执）。普通文本走 z.string 分支，结构化消息走这里，inputSchema 用 union 合并两条路。'''),
    (67, 'before', r'''inputSchema 三字段：to（收件人——队友名/「*」广播/uds: 本地 socket/bridge: 跨机会话）、summary（5-10 词摘要，字符串消息必填）、message（字符串或结构化消息）。to 的 describe 按 UDS_INBOX 特性分档——功能没开时模型根本看不到 bridge 语法。'''),
    (133, 'before', r'''findTeammateColor：从 AppState 的 teamContext 里按名字反查队友颜色。颜色是纯 UI 装饰（消息渲染时发送方/接收方各着其色），查不到就 undefined——显示层对缺失颜色有默认值，这里不做兜底。'''),
    (149, 'before', r'''handleMessage：点对点消息 = 写收件人 mailbox + 回执。writeToMailbox 是异步投递（对方下一轮工具调用时才会读到），返回的 routing 对象供 UI 渲染「谁→谁」的气泡。'''),
    (191, 'before', r'''handleBroadcast：广播前的双重存在性校验——没在团队上下文里、或团队文件不存在，直接抛错（错误消息里连补救方法都给了：用 Teammate spawnTeam 或设 CLAUDE_CODE_TEAM_NAME）。广播是线性成本动作，先确认收件人集合非空。'''),
    (220, 'before', r'''收件人收集：遍历团队成员、按名字（大小写不敏感）排除自己——给自己发广播没有意义。排除后为空时返回成功但 recipients 为空数组：空广播是合法的 no-op，不该报错。'''),
    (268, 'before', r'''handleShutdownRequest：生成 shutdown 请求 ID 后写 mailbox。请求 ID 由 generateRequestId('shutdown', targetName) 生成——同一目标多个请求靠 ID 区分回执。关机协议是「请求—响应」配对，request_id 是关联键。'''),
    (305, 'before', r'''handleShutdownApproval 是本文件最复杂的分支：批准关机 = 给 team-lead 发回执 + 自己想办法停机。停机方式按 backendType 分流——in-process 队友 abort 自己的 controller（任务在同一个 Node 进程里），其他后端走 gracefulShutdown 退进程。'''),
    (348, 'before', r'''in-process 分支：先按 agentId 在 AppState.tasks 里找自己的任务，abortController.abort() 直接中止当前循环。找不到任务只记 debug 日志不抛错——回执已发出，停机失败由 team-lead 侧超时兜底。'''),
    (367, 'before', r'''非 in-process 分支的兜底与收尾：先试一次 AppState 查找（后端类型标错但任务其实在册的情况），命中就 abort 并提前返回；都不命中才 setImmediate(gracefulShutdown(0))——异步退场让当前 tool_result 有机会先写完。'''),
    (401, 'before', r'''handleShutdownRejection：拒绝关机必须带 reason（schema 层已强制），原样回传给 team-lead。拒绝是协作协议的一部分——队长需要知道「为什么不肯停」才能决定强杀还是等。'''),
    (434, 'before', r'''handlePlanApproval：只有 team-lead 能批计划（isTeamLead 校验，队友批自己的计划是提权漏洞）。批了之后把队长的权限模式一并继承给队友——plan 模式下批准的计划，队友落地时用 default 而非继续锁在 plan 里。'''),
    (448, 'after', r'''modeToInherit：队长在 plan 模式时批计划，队友继承 default——否则队友拿着 plan 模式没法写代码，计划批了等于白批。'''),
    (478, 'before', r'''handlePlanRejection：驳回必须带 feedback（模型可传的默认值是「Plan needs revision」）。与批准同构——回执写 mailbox，权限模式不传递。'''),
    (520, 'before', r'''buildTool 主结构。searchHint 直说这是 swarm 协议——本工具整个是 agent 间通信层，不是给人用的。'''),
    (535, 'before', r'''isEnabled = isAgentSwarmsEnabled()：没开 agent swarms 时工具整个消失——单代理会话里给模型一个「给队友发消息」的工具只会制造困惑。'''),
    (539, 'before', r'''isReadOnly 按 message 类型动态判定：纯文本消息只读（不落盘、不改状态），结构化消息（关机/审批）有副作用——权限系统据此决定要不要过审批。'''),
    (543, 'before', r'''backfillObservableInput：把 to/message 拍平成一阶字段（type/recipient/content/request_id/approve）供观测与分类器消费——union 输入对下游不友好，拍平后所有消费者看到同一套键。结构化消息直接 return（已有 type 字段）。'''),
    (571, 'before', r'''toAutoClassifierInput：喂给自动权限分类器的摘要按消息类型分格式——关机请求/响应、计划审批各有各的人类可读形式，与 backfill 的拍平字段一一对应。'''),
    (585, 'before', r'''checkPermissions：本地 teammate 消息直接 allow（swarm 内部通信是受信通道）；bridge: 跨机会话强制 ask 且带 safetyCheck 级 decisionReason——注释明说这条必须在 bypassPermissions（步骤 1g）和 auto 模式白名单之前拦截：跨机 prompt injection 必须对绕过模式免疫，classifierApprovable: false 把自动批准的路也焊死。'''),
    (604, 'before', r'''validateInput 是 errorCode 9 家族（输入格式错误）：to 空、地址 target 空、含 @（一个会话只有一个团队，@ 语法是误解）、字符串消息缺 summary、结构化消息禁广播、禁跨会话发送结构化消息、shutdown_response 必须回给 team-lead、拒绝必须带 reason。每条错误消息都直接教模型正确写法。'''),
    (742, 'before', r'''call() 的跨机会话分支（UDS_INBOX 特性下）：bridge: 走 postInterClaudeMessage 经 Anthropic 服务器中转到另一台机器；uds: 走本地 Unix socket。两条路都在 call() 里重新校验 bridge 活性——checkPermissions 会阻塞在用户审批上（可能几分钟），期间 bridge 可能已断，不重检就会发出 from=unknown 的孤儿消息。'''),
    (802, 'before', r'''本地子代理按名路由：先查 agentNameRegistry（注册名），再按 toAgentId 格式兜底（原始 ID）。running 状态的消息进 queuePendingMessage（下一轮工具调用时送达）；stopped 的自动 resumeAgentBackground 后台拉起并把消息当 prompt——「给已停的代理发消息」不是错误，是唤醒。任务被逐出状态的走磁盘 transcript 恢复。'''),
    (876, 'before', r'''ambient-team 回落：以上都不命中（没有注册代理）才按团队 mailbox 语义处理——字符串消息点对点/广播，结构化消息进 switch。'''),
    (887, 'before', r'''结构化消息分派：shutdown_request 发请求、shutdown_response 按 approve 分流批准/拒绝、plan_approval_response 按 approve 分流批准/驳回。所有分支共用一个事实——结构化消息只走本地团队，跨会话只送纯文本（validateInput 已拦）。'''),
]
